package dev.networkwatch;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class AnalyzerTest{@Test void scoresExplainableRulesAndRedacts(){var a=new Analyzer();var events=new ArrayList<Analyzer.Event>();for(int i=0;i<5;i++)events.add(new Analyzer.Event(i,"alex@example.test","192.0.2.1","auth",false,0,"demo-a"));events.add(new Analyzer.Event(6,"alex@example.test","192.0.2.2","traffic",true,11_000_000,"demo-b"));events.add(new Analyzer.Event(7,"alex@example.test","192.0.2.3","auth",true,0,"demo-c"));var r=a.analyze(events);assertEquals(95,r.risk());assertFalse(r.subject().contains("alex"));assertEquals(3,r.findings().size());}@Test void rejectsMalformedCsv(){assertThrows(IllegalArgumentException.class,()->new Analyzer().parse(List.of("bad,line")));}}
